const extractSearchCandidates = (title: string): string[] => {
  const junk = /\b(no reserve price|reserve price|men['s]*|women['s]*|unisex|full set|with box.*|cased|vintage|\d{4}-\d{4}|\d{4}\+?)\b/gi
  const dotMatch = title.match(/\b\d{3}\.\d{2}(?:\.\d{2})*(?:\.\d{2}\.\d{3})?\b/)
  let dotPrefix = ''
  if (dotMatch) {
    const parts = dotMatch[0].split('.')
    if (parts.length >= 3) {
      dotPrefix = `${parts[0]}.${parts[1]}.${parts[2]}`
    }
  }
  const alphaRefs: string[] = []
  const alphaMatches = title.match(/\b[A-Za-z]{0,3}\d{3,6}[A-Za-z0-9]*\b/g)
  if (alphaMatches) {
    for (const m of alphaMatches) {
      if (!/^\d{4}$/.test(m)) {
        alphaRefs.push(m)
      }
    }
  }
  const segments = title.split(/\s*[-–—|/]\s*/).map(s => s.trim()).filter(Boolean)
  const brand = segments[0] ? segments[0].replace(junk, '').trim() : ''
  const model = segments[1] ? segments[1].replace(junk, '').trim() : ''
  const brandModel = [brand, model].filter(Boolean).join(' ')
  const candidates: string[] = []
  if (dotPrefix) candidates.push(dotPrefix)
  for (const ref of alphaRefs) candidates.push(ref)
  if (brandModel) candidates.push(brandModel)
  if (brand) candidates.push(brand)
  return Array.from(new Set(candidates)).filter(c => c && c.length >= 2)
}

